        .iter()
        .map(|c| deserialize(c))
        .collect::<Result<Vec<_>, _>>()
    {
        Ok(commitments) => commitments,
        Err(_) => {
            assert!(test.output.is_none());
            return;
        }
    };

    let cells = match cells
        .iter()
        .map(|cell| deserialize(cell))
        .collect::<Result<Vec<_>, _>>()
    {
        Ok(cells) => cells,
        Err(_) => {
            assert!(test.output.is_none());
            return;
        }
    };

    let proofs = match proofs
        .iter()
        .map(|proof| deserialize(proof))
        .collect::<Result<Vec<_>, _>>()
